def transform(grid):
    """Color the 8-neighbor rim around a drawing when it encloses a zero region.

    Enclosed zero cells adjacent to the 1-stroke (including diagonal contact) are
    colored 3; exterior zero cells in that rim are colored 2. Deep interiors and
    unrelated background remain unchanged.
    """
    h, w = len(grid), len(grid[0])
    exterior = set()
    q = deque()
    for r in range(h):
        for c in range(w):
            if (r == 0 or r == h - 1 or c == 0 or c == w - 1) and grid[r][c] == 0:
                if (r, c) not in exterior:
                    exterior.add((r, c))
                    q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr, nc) not in exterior:
                exterior.add((nr, nc))
                q.append((nr, nc))

    has_enclosed = any(grid[r][c] == 0 and (r, c) not in exterior
                       for r in range(h) for c in range(w))
    out = [row[:] for row in grid]
    if not has_enclosed:
        return out

    # Rim cells are zeros touching a 1 in the 8-neighborhood. Classify by
    # 4-connected zero-region reachability from the canvas edge.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            touches_stroke = any(
                0 <= r + dr < h and 0 <= c + dc < w and grid[r + dr][c + dc] == 1
                for dr in (-1, 0, 1) for dc in (-1, 0, 1)
                if dr or dc
            )
            if touches_stroke:
                out[r][c] = 2 if (r, c) in exterior else 3
    return out


def main():
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))


if __name__ == '__main__':
    main()
