    exterior = set()
    q = deque()
    for r in range(h):
        for c in range(w):
            if (r in (0, h - 1) or c in (0, w - 1)) and grid[r][c] == 0:
                exterior.add((r, c))
                q.append((r, c))
    forpop = ((1, 0), (-1, 0), (0, 1), (0, -1))
    while q:
        r, c = q.popleft()
        for dr, dc in forpop:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr, nc) not in exterior:
                exterior.add((nr, nc))
                q.append((nr, nc))

    # Find 4-connected stroke components and retain those touching an enclosed
    # zero region. Such components are the closed outlines to be highlighted.
    seen = set()
    active = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            comp = set()
            q = [(r, c)]
            seen.add((r, c))
            while q:
                x, y = q.pop()
                comp.add((x, y))
                for dx, dy in forpop:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 1 and (nx, ny) not in seen:
