                and grid[x + dx][y + dy] == 0
                and (x + dx, y + dy) not in exterior
                for x, y in comp for dx, dy in forpop
            )
            if encloses:
                active.update(comp)

    out = [row[:] for row in grid]
    # Paint the eight-neighbor rim of active strokes; distinguish the exterior
    # rim (2) from the enclosed-side rim (3). More distant zeros are untouched.
    for r, c in active:
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if not (dr or dc):
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0:
                    out[nr][nc] = 2 if (nr, nc) in exterior else 3
    return out


